{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/1"],
      "relevance": "상담사가 '그 반응이 팀원에게 어떤 영향을 주기를 바라셨어요?'라고 질문한 것은 내담자가 자신의 말과 태도로 팀원이 복종하거나 위축되기를 기대했던 특권의식적 기대를 탐색하는 것. 상황 사례 1에서 신입 직원의 지적에 '실적 내고 나서 얘기해'라고 면박을 준 패턴과 동일함."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '팀장으로서 할 말을 한 건데'라고 정당화하는 것은 '성과를 내면 사람들은 내 방식에 토를 달지 못할 것'이라는 가정이 작동하고 있음을 보여줌. 상황 사례 1에서 신입 직원의 규정 지적을 '실적 내고 나서 얘기해'로 무력화한 것과 같은 구조."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '이 정도면 됐죠' 하는 태도에 욱했다고 한 것은 목표 미달 직원(본인 기준 '능력 없는 사람')이 자신의 지적에 반론하는 것 자체가 참을 수 없다는 태도와 연결됨. 상황 사례 1에서 신입 직원의 조심스러운 지적을 경멸한 패턴과 유사."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '팀장으로서 할 말을 한 건데'라며 자신의 위치(팀장)를 근거로 폭언을 정당화하는 것은 내용을 검토하기보다 상대의 자격·위치를 문제 삼아 무력화하는 전략. 상황 사례 0에서 인사팀장의 징계 통보에 '실적 한 번 못 내 본 것들이'라고 반격한 것과 같은 패턴."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '폭언이 된 겁니다'라는 인사팀의 판단에 억울함을 느끼는 것은, 같은 취급을 받는 순간 특별함이 무너진다는 공포가 작동하고 있음을 시사. 상황 사례 0에서 직급과 무관하게 폭언이 징계 사유라는 통보에 분노한 것과 연결."
    }
  ]
}

